"""
    Return the classical-basis labels based on a vector dimension.

    Parameters
    ----------
    dim : int
        The dimension of the basis to generate labels for (e.g.
        2 for a single classical bit).

    Returns
    -------
    list of strs
    """
def cl_labels(dim: Any) -> object {
    if (dim == 0) {
        return [];
    }
    if (dim == 1) {
        return [''];
    }
    return [("%d" % i) for i in range(dim)];
}

