"""
    Build SMT formula footer

    Args:
        id1 (str): ID of policy 1 in SMT formula
        id2 (str, optional): ID of policy 2 in SMT formula. Defaults to None.

    Returns:
        str: SMT footer
    """
def footer(id1: Any, id2: Any = None) -> object {
    smt = '(assert {}.allows)\n'.format(id1);
    if id2 {
        smt += '(assert (or {0}.denies {0}.neutral))\n'.format(id2);
    }
    smt += '(check-sat)\n';
    smt += '(get-model)\n';
    return smt;
}

"""
    KlipChop func to to convert text into unique lines
    """
def main(textlines: Any, messagefunc: Any, config: Any) -> object {
    result = `list();
    count = 0;
    for line in textlines() {
        if (line not in result) {
            result.append(line);
            count += 1;
        }
    }
    if config['sort'] {
        result = sorted(result);
    }
    result = '\n'.join(result);
    messagefunc(f'{count} unique lines');
    return result;
}

